    #private;
    constructor(options: NodeKnorviaBuiltinProviderConfigSourceOptions);
    get activeFilePath(): string;
    read(): Promise<ProviderConfigLayerSnapshot>;
    applyRemoteRelease(release: KnorviaBuiltinRelease): Promise<ApplyKnorviaBuiltinReleaseResult>;
    onDidChange(listener: (reason: string) => void): () => void;
