  late = new Synchronizer(lateOptions); applyGate = deferred();
  const latePending = late.refresh(); await flush(); const reports = events.length;
  late.dispose(); applyGate.resolve("updated"); assert.equal(await latePending, "updated"); assert.equal(events.length, reports);
  assert.deepEqual(JSON.parse(files.get(lateOptions.controlFilePath)!), { schemaVersion: 1, endpointKey: "synthetic-late", leaseUntil: 0, nextEligibleAt: now + 50, failureCount: 0 }); applyGate = undefined;

  const initialGate = deferred<string>(); const initial = new Synchronizer({ ...lateOptions, resolveEndpointKey: () => initialGate.promise });
  const initialPending = initial.refresh(); const initialWrites = writes.length; initial.dispose(); initialGate.resolve("synthetic-start");
  assert.equal(await initialPending, "disposed"); assert.equal(writes.length, initialWrites);
