import { watch, type FSWatcher } from "node:fs";
import { createHash } from "node:crypto";
import { mkdir, readFile } from "node:fs/promises";
import { basename, dirname, resolve } from "node:path";
import type { ProviderConfigLayerSnapshot, ProviderSource } from "@knorvia/provider";
import { atomicWritePrivateTextFile, withFileLock } from "@knorvia/shared/node";
import {
  decodeKnorviaBuiltinRelease,
  encodeKnorviaBuiltinRelease,
  serializeKnorviaBuiltinRelease,
  type KnorviaBuiltinRelease,
} from "./builtin-release.js";

export interface NodeKnorviaBuiltinProviderConfigSourceOptions {
  readonly bundledFilePath: string;
  readonly activeFilePath?: string;
  readonly watch?: boolean;
}

export type ApplyKnorviaBuiltinReleaseResult = "updated" | "unchanged" | "stale";

/** Bundled、Active/LKG 与 Remote 共用同一 Release，并最终发布为现有 Config Snapshot。 */
export class NodeKnorviaBuiltinProviderConfigSource implements ProviderSource<ProviderConfigLayerSnapshot> {
  #bundledFilePath: string;
  #activeFilePath: string;
  #sourceKey: string;
  #watchEnabled: boolean;
  #listeners = new Set<(reason: string) => void>();
  #watcher: FSWatcher | null = null;
  #observedSignature: string | null = null;
  #watchTail: Promise<void> = Promise.resolve();
  #disposed = false;

  constructor(options: NodeKnorviaBuiltinProviderConfigSourceOptions) {
    const bundledFilePath = options.bundledFilePath.trim();
    if (!bundledFilePath) {
      throw new Error("Knorvia Studio Built-in bundledFilePath 不能为空");
    }
    this.#bundledFilePath = bundledFilePath;
    this.#activeFilePath = options.activeFilePath?.trim() || bundledFilePath;
    this.#sourceKey = createHash("sha256").update(resolve(this.#activeFilePath)).digest("hex");
    this.#watchEnabled = options.watch !== false;
  }

  get activeFilePath(): string {
    return this.#activeFilePath;
  }

  async read(): Promise<ProviderConfigLayerSnapshot> {
    this.#assertNotDisposed();
    let release: KnorviaBuiltinRelease;
    try {
      await this.#ensureWatcher();
      release = await withFileLock(this.#activeFilePath, () => this.#readAndMaterializeLocked());
    } catch {
      const bundled = await readReleaseCandidate(this.#bundledFilePath);
      release = selectReleaseCandidate(bundled, null);
    }
    this.#observedSignature ??= releaseSignature(release);
    return createLayerSnapshot(release, this.#sourceKey);
  }

  async applyRemoteRelease(
    release: KnorviaBuiltinRelease,
  ): Promise<ApplyKnorviaBuiltinReleaseResult> {
    this.#assertNotDisposed();
    await this.#ensureWatcher();
    const result = await withFileLock(
      this.#activeFilePath,
      async (): Promise<ApplyKnorviaBuiltinReleaseResult> => {
        this.#assertNotDisposed();
        const current = await this.#readAndMaterializeLocked();
        this.#assertNotDisposed();
        if (release.revision < current.revision) {
          return "stale";
        }
        if (release.revision === current.revision) {
          if (serializeKnorviaBuiltinRelease(release) === serializeKnorviaBuiltinRelease(current)) {
            return "unchanged";
          }
          throw new Error(`Knorvia Studio Built-in 相同 revision ${release.revision} 对应不同内容`);
        }
        await this.#writeActiveLocked(release);
        this.#observedSignature = releaseSignature(release);
        return "updated";
      },
    );
    if (result === "updated" && !this.#disposed) {
      this.#emit("remote-updated");
    }
    return result;
  }

  onDidChange(listener: (reason: string) => void): () => void {
    this.#assertNotDisposed();
    this.#listeners.add(listener);
    return () => this.#listeners.delete(listener);
  }

  dispose(): void {
    if (this.#disposed) {
      return;
    }
    this.#disposed = true;
    this.#watcher?.close();
    this.#watcher = null;
    this.#listeners.clear();
  }

  #assertNotDisposed(): void {
    if (this.#disposed) {
      throw new Error("NodeKnorviaBuiltinProviderConfigSource 已 dispose");
    }
  }

  async #ensureWatcher(): Promise<void> {
    await mkdir(dirname(this.#activeFilePath), { recursive: true });
    if (!this.#watchEnabled || this.#watcher || this.#disposed) {
      return;
    }
    const target = basename(this.#activeFilePath);
    this.#watcher = watch(dirname(this.#activeFilePath), (_eventType, fileName) => {
      if (fileName === null || fileName.toString() === target) {
        this.#scheduleWatchRead();
      }
    });
    this.#watcher.on("error", () => this.#emit("watch-error"));
  }

  #scheduleWatchRead(): void {
    this.#watchTail = this.#watchTail.then(async () => {
      if (this.#disposed) {
        return;
      }
      try {
        const release = await withFileLock(this.#activeFilePath, () =>
          this.#readAndMaterializeLocked(),
        );
        const signature = releaseSignature(release);
        if (this.#disposed || signature === this.#observedSignature) {
          return;
        }
        this.#observedSignature = signature;
        this.#emit("file-changed");
      } catch {
        this.#emit("watch-error");
      }
    });
  }

  async #readAndMaterializeLocked(): Promise<KnorviaBuiltinRelease> {
    const [bundled, active] = await Promise.all([
      readReleaseCandidate(this.#bundledFilePath),
      this.#activeFilePath === this.#bundledFilePath
        ? Promise.resolve(null)
        : readReleaseCandidate(this.#activeFilePath),
    ]);
    const selected = selectReleaseCandidate(bundled, active);
    if (this.#activeFilePath !== this.#bundledFilePath) {
      const activeSignature = active?.release ? releaseSignature(active.release) : null;
      if (activeSignature !== releaseSignature(selected)) {
        await this.#writeActiveLocked(selected);
      }
    }
    return selected;
  }

  async #writeActiveLocked(release: KnorviaBuiltinRelease): Promise<void> {
    this.#assertNotDisposed();
    await atomicWritePrivateTextFile(
      this.#activeFilePath,
      JSON.stringify(encodeKnorviaBuiltinRelease(release), null, 2),
    );
  }

  #emit(reason: string): void {
    if (this.#disposed) {
      return;
    }
    for (const listener of this.#listeners) {
      listener(reason);
    }
  }
}

export function createNodeKnorviaBuiltinProviderConfigSource(
  options: NodeKnorviaBuiltinProviderConfigSourceOptions,
): NodeKnorviaBuiltinProviderConfigSource {
  return new NodeKnorviaBuiltinProviderConfigSource(options);
}

type ReleaseCandidate = {
  release?: KnorviaBuiltinRelease;
  error?: unknown;
} | null;

async function readReleaseCandidate(filePath: string): Promise<ReleaseCandidate> {
  try {
    const text = await readFile(filePath, "utf8");
    return { release: decodeKnorviaBuiltinRelease(JSON.parse(text)) };
  } catch (error) {
    if (typeof error === "object" && error !== null && "code" in error && error.code === "ENOENT") {
      return null;
    }
    return { error };
  }
}

function selectReleaseCandidate(
  bundled: ReleaseCandidate,
  active: ReleaseCandidate,
): KnorviaBuiltinRelease {
  if (
    bundled?.release &&
    active?.release &&
    bundled.release.revision === active.release.revision &&
    serializeKnorviaBuiltinRelease(bundled.release) !==
      serializeKnorviaBuiltinRelease(active.release)
  ) {
    return bundled.release;
  }
  const releases = [bundled?.release, active?.release].filter(
    (release): release is KnorviaBuiltinRelease => release !== undefined,
  );
  const first = releases[0];
  if (first === undefined) {
    throw new AggregateError(
      [bundled?.error, active?.error].filter((error) => error !== undefined),
      "Bundled 与 Active Knorvia Studio Built-in Release 均不可用",
    );
  }
  let selected = first;
  for (const release of releases.slice(1)) {
    if (release.revision > selected.revision) {
      selected = release;
    }
  }
  return selected;
}

function releaseSignature(release: KnorviaBuiltinRelease): string {
  return `${release.revision}:${serializeKnorviaBuiltinRelease(release)}`;
}

function createLayerSnapshot(
  release: KnorviaBuiltinRelease,
  sourceKey: string,
): ProviderConfigLayerSnapshot {
  return Object.freeze({
    revision: `builtin:${release.revision}:${sourceKey}`,
    providers: release.config.providers,
    providerTemplates: release.config.providerTemplates,
    models: release.config.modelConfigRules,
  });
}

import { randomUUID } from "node:crypto";
import { readFile } from "node:fs/promises";
import { atomicWritePrivateTextFile, withFileLock } from "@knorvia/shared/node";
import type { NodeKnorviaBuiltinProviderConfigSource } from "./builtin-provider-config-source.js";
import type { KnorviaBuiltinRelease } from "./builtin-release.js";

const HOUR_MS = 60 * 60 * 1_000;

export type KnorviaBuiltinRefreshResult =
  | "updated"
  | "unchanged"
  | "stale"
  | "missing"
  | "skipped"
  | "disposed";

export interface KnorviaBuiltinRemoteSynchronizerOptions {
  readonly source: NodeKnorviaBuiltinProviderConfigSource;
  readonly controlFilePath: string;
  readonly resolveEndpointKey: () => string | Promise<string>;
  readonly fetchRelease: (
    endpointKey: string,
    signal: AbortSignal,
  ) => Promise<KnorviaBuiltinRelease | null>;
  readonly onRefreshResult?: (event: KnorviaBuiltinRefreshEvent) => void;
  readonly now?: () => number;
  readonly successIntervalMs?: number;
  readonly leaseDurationMs?: number;
  readonly failureBaseDelayMs?: number;
  readonly failureMaxDelayMs?: number;
}

export interface KnorviaBuiltinRefreshEvent {
  readonly result: KnorviaBuiltinRefreshResult;
  readonly reason?: "lease-held" | "not-due" | "endpoint-changed";
  readonly revision?: number;
}

interface RefreshControl {
  readonly schemaVersion: 1;
  readonly endpointKey: string;
  readonly leaseId?: string;
  readonly leaseUntil: number;
  readonly nextEligibleAt: number;
  readonly failureCount: number;
}

/** Environment 共享控制文件合并多进程刷新；网络期间不持有文件锁。 */
export class KnorviaBuiltinRemoteSynchronizer {
  readonly #options: KnorviaBuiltinRemoteSynchronizerOptions;
  readonly #now: () => number;
  #inflight: Promise<KnorviaBuiltinRefreshResult> | null = null;
  #disposed = false;
  #abortController: AbortController | null = null;

  constructor(options: KnorviaBuiltinRemoteSynchronizerOptions) {
    this.#options = options;
    this.#now = options.now ?? Date.now;
  }

  refresh(options: { readonly force?: boolean } = {}): Promise<KnorviaBuiltinRefreshResult> {
    if (this.#disposed) {
      return Promise.resolve("disposed");
    }
    if (this.#inflight) {
      return this.#inflight;
    }

    const controller = new AbortController();
    this.#abortController = controller;
    const force = options.force === true;
    const promise = this.#refreshInternal(force, controller.signal).finally(() => {
      if (this.#inflight === promise) {
        this.#inflight = null;
        this.#abortController = null;
      }
    });
    this.#inflight = promise;
    return promise;
  }

  dispose(): void {
    this.#disposed = true;
    this.#abortController?.abort();
  }

  async #refreshInternal(
    force: boolean,
    signal: AbortSignal,
  ): Promise<KnorviaBuiltinRefreshResult> {
    const endpoint = (await this.#options.resolveEndpointKey()).trim();
    if (this.#disposed) {
      return "disposed";
    }
    if (!endpoint) {
      throw new Error("Knorvia Studio Built-in 远端 Endpoint 不能为空");
    }

    const leaseId = randomUUID();
    const acquired = await withFileLock(
      this.#options.controlFilePath,
      async (): Promise<true | "lease-held" | "not-due"> => {
        const now = this.#now();
        const current = await readControl(this.#options.controlFilePath);
        const same = current.endpointKey === endpoint;
        if (same && current.leaseUntil > now) {
          return "lease-held";
        }
        if (!force && same && current.nextEligibleAt > now) {
          return "not-due";
        }
        await writeControl(this.#options.controlFilePath, {
          schemaVersion: 1,
          endpointKey: endpoint,
          leaseId,
          leaseUntil: now + (this.#options.leaseDurationMs ?? 30000),
          nextEligibleAt: same ? current.nextEligibleAt : 0,
          failureCount: same ? current.failureCount : 0,
        });
        return true;
      },
    );

    if (acquired !== true) {
      this.#report({ result: "skipped", reason: acquired });
      return "skipped";
    }

    try {
      signal.throwIfAborted();
      const release = await this.#options.fetchRelease(endpoint, signal);
      if (this.#disposed) {
        await this.#finishLease(endpoint, leaseId, "cancelled");
        return "disposed";
      }

      const nextEndpoint = (await this.#options.resolveEndpointKey()).trim();
      signal.throwIfAborted();
      if (nextEndpoint !== endpoint) {
        await this.#finishLease(endpoint, leaseId, true);
        this.#report({ result: "skipped", reason: "endpoint-changed" });
        return "skipped";
      }

      const result = release ? await this.#options.source.applyRemoteRelease(release) : "missing";
      await this.#finishLease(endpoint, leaseId, true);
      this.#report({ result, ...(release ? { revision: release.revision } : {}) });
      return result;
    } catch (error) {
      await this.#finishLease(endpoint, leaseId, this.#disposed ? "cancelled" : false);
      if (this.#disposed) {
        return "disposed";
      }
      throw error;
    }
  }

  #report(event: KnorviaBuiltinRefreshEvent): void {
    if (this.#disposed) {
      return;
    }
    try {
      this.#options.onRefreshResult?.(event);
    } catch {
      // A reporting callback does not determine the refresh outcome.
    }
  }

  async #finishLease(
    endpoint: string,
    leaseId: string,
    success: boolean | "cancelled",
  ): Promise<void> {
    await withFileLock(this.#options.controlFilePath, async () => {
      const current = await readControl(this.#options.controlFilePath);
      if (current.endpointKey !== endpoint || current.leaseId !== leaseId) {
        return;
      }

      const failureCount =
        success === "cancelled" ? current.failureCount : success ? 0 : current.failureCount + 1;
      const delay =
        success === "cancelled"
          ? 0
          : success
            ? (this.#options.successIntervalMs ?? HOUR_MS)
            : Math.min(
                (this.#options.failureBaseDelayMs ?? 60000) * 2 ** Math.max(0, failureCount - 1),
                this.#options.failureMaxDelayMs ?? HOUR_MS,
              );
      await writeControl(this.#options.controlFilePath, {
        schemaVersion: 1,
        endpointKey: endpoint,
        leaseUntil: 0,
        nextEligibleAt: this.#now() + delay,
        failureCount,
      });
    });
  }
}

async function readControl(filePath: string): Promise<RefreshControl> {
  let raw: string;
  try {
    raw = await readFile(filePath, "utf8");
  } catch (error) {
    if (typeof error === "object" && error !== null && "code" in error && error.code === "ENOENT") {
      return emptyControl();
    }
    throw error;
  }

  try {
    const parsed: unknown = JSON.parse(raw);
    return isRefreshControl(parsed) ? parsed : emptyControl();
  } catch {
    return emptyControl();
  }
}

function writeControl(filePath: string, control: RefreshControl): Promise<void> {
  return atomicWritePrivateTextFile(filePath, JSON.stringify(control, null, 2));
}

function isRefreshControl(value: unknown): value is RefreshControl {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    return false;
  }
  const control = value as Record<string, unknown>;
  return (
    control.schemaVersion === 1 &&
    typeof control.endpointKey === "string" &&
    (control.leaseId === undefined || typeof control.leaseId === "string") &&
    typeof control.leaseUntil === "number" &&
    typeof control.nextEligibleAt === "number" &&
    Number.isInteger(control.failureCount) &&
    (control.failureCount as number) >= 0
  );
}

function emptyControl(): RefreshControl {
  return {
    schemaVersion: 1,
    endpointKey: "",
    leaseUntil: 0,
    nextEligibleAt: 0,
    failureCount: 0,
  };
}

import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { resolve } from "node:path";
import { test } from "node:test";
import { ModelConfigRules, ProviderConfigMap, ProviderTemplateMap } from "@knorvia/provider";
import type { KnorviaBuiltinRelease } from "../src/builtin-release.js";

function deferred<T>() {
  let resolve!: (value: T) => void;
  const promise = new Promise<T>((yes) => {
    resolve = yes;
  });
  return { promise, resolve };
}
async function flush() {
  for (let turn = 0; turn < 40; turn++) await Promise.resolve();
}

test("synthetic release ports preserve trusted cache selection, writes, live observers and disposal phases", async (t) => {
  const files = new Map<string, string>();
  const readErrors = new Map<string, unknown>();
  const releases = new Map<string, KnorviaBuiltinRelease>();
  const tags = new WeakMap<KnorviaBuiltinRelease, string>();
  const writes: { path: string; text: string }[] = [];
  const reads: string[] = [];
  const folders: string[] = [];
  let mkdirError: unknown;
  let lockError: unknown;
  let writeError: unknown;
  let writeGate: ReturnType<typeof deferred<void>> | undefined;
  const tails = new Map<string, Promise<void>>();
  function release(revision: number, tag: string): KnorviaBuiltinRelease {
    const value: KnorviaBuiltinRelease = {
      schemaVersion: 1,
      revision,
      config: {
        providers: ProviderConfigMap.empty(),
        providerTemplates: ProviderTemplateMap.empty(),
        modelConfigRules: ModelConfigRules.empty(),
      },
    };
    tags.set(value, tag);
    releases.set(`${revision}:${tag}`, value);
    return value;
  }
  function encode(value: KnorviaBuiltinRelease) {
    return { schemaVersion: 1, revision: value.revision, syntheticTag: tags.get(value)! };
  }
  function serialize(value: KnorviaBuiltinRelease) {
    return JSON.stringify(encode(value));
  }
  function put(path: string, value: KnorviaBuiltinRelease) {
    files.set(path, JSON.stringify(encode(value)));
  }
  type Watch = {
    callback: (event: string, name: string | Buffer | null) => void;
    error?: () => void;
    closes: number;
    closeError?: Error;
  };
  const watchers: Watch[] = [];
  t.mock.module("node:fs", {
    namedExports: {
      watch(path: string, callback: Watch["callback"]) {
        folders.push(`watch:${path}`);
        const watcher: Watch = { callback, closes: 0 };
        watchers.push(watcher);
        return {
          on(event: string, listener: () => void) {
            assert.equal(event, "error");
            watcher.error = listener;
            return this;
          },
          close() {
            watcher.closes++;
            if (watcher.closeError) throw watcher.closeError;
          },
        };
      },
    },
  });
  t.mock.module("node:fs/promises", {
    namedExports: {
      async mkdir(path: string, options: unknown) {
        folders.push(path);
        assert.deepEqual(options, { recursive: true });
        if (mkdirError) throw mkdirError;
      },
      async readFile(path: string, encoding: string) {
        reads.push(path);
        assert.equal(encoding, "utf8");
        if (readErrors.has(path)) throw readErrors.get(path);
        if (!files.has(path))
          throw Object.assign(new Error("synthetic missing"), { code: "ENOENT" });
        return files.get(path)!;
      },
    },
  });
  t.mock.module("@knorvia/shared/node", {
    namedExports: {
      async atomicWritePrivateTextFile(path: string, text: string) {
        writes.push({ path, text });
        if (writeError) throw writeError;
        if (writeGate) await writeGate.promise;
        files.set(path, text);
      },
      withFileLock<T>(path: string, action: () => Promise<T>) {
        if (lockError) return Promise.reject(lockError);
        const pending = (tails.get(path) ?? Promise.resolve()).then(action);
        tails.set(
          path,
          pending.then(
            () => {},
            () => {},
          ),
        );
        return pending;
      },
    },
  });
  t.mock.module(new URL("../src/builtin-release.ts", import.meta.url).href, {
    namedExports: {
      encodeKnorviaBuiltinRelease: encode,
      serializeKnorviaBuiltinRelease: serialize,
      decodeKnorviaBuiltinRelease(input: { revision: number; syntheticTag: string }) {
        const value = releases.get(`${input.revision}:${input.syntheticTag}`);
        if (!value) throw new Error("synthetic decode invalid");
        return value;
      },
    },
  });
  const {
    NodeKnorviaBuiltinProviderConfigSource: Source,
    createNodeKnorviaBuiltinProviderConfigSource: create,
  } = await import("../src/builtin-provider-config-source.js");
  assert.throws(() => create({ bundledFilePath: " " }), {
    message: "Knorvia Studio Built-in bundledFilePath 不能为空",
  });
  const bundle = release(1, "bundle"),
    active = release(2, "active"),
    newer = release(3, "newer");
  put("synthetic/bundle", bundle);
  put("synthetic/active", active);
  const options = {
    bundledFilePath: " synthetic/bundle ",
    activeFilePath: " synthetic/active ",
    watch: false,
  };
  const source = create(options);
  options.activeFilePath = "synthetic/mutated";
  assert.equal(source.activeFilePath, "synthetic/active");
  assert.deepEqual(Object.keys(source), []);
  const snapshot = await source.read();
  assert.equal(
    snapshot.revision,
    `builtin:2:${createHash("sha256").update(resolve("synthetic/active")).digest("hex")}`,
  );
  assert.equal(snapshot.providers, active.config.providers);
  assert.equal(snapshot.providerTemplates, active.config.providerTemplates);
  assert.equal(snapshot.models, active.config.modelConfigRules);
  assert.deepEqual(Object.keys(snapshot), ["revision", "providers", "providerTemplates", "models"]);
  assert.equal(Object.isFrozen(snapshot), true);
  assert.equal(writes.length, 0);
  assert.equal(watchers.length, 0);
  put("synthetic/other", active);
  const other = new Source({
    bundledFilePath: "synthetic/bundle",
    activeFilePath: "synthetic/other",
    watch: false,
  });
  assert.notEqual((await other.read()).revision, snapshot.revision);
  other.dispose();
  assert.equal(await source.applyRemoteRelease(bundle), "stale");
  assert.equal(await source.applyRemoteRelease(active), "unchanged");
  await assert.rejects(source.applyRemoteRelease(release(2, "conflict")), {
    message: "Knorvia Studio Built-in 相同 revision 2 对应不同内容",
  });
  assert.equal(writes.length, 0);
  const events: string[] = [];
  const late = (reason: string) => events.push(`late:${reason}`);
  let removeSecond = () => {};
  const first = (reason: string) => {
    events.push(`first:${reason}`);
    removeSecond();
    source.onDidChange(late);
  };
  source.onDidChange(first);
  source.onDidChange(first);
  removeSecond = source.onDidChange((reason) => events.push(`second:${reason}`));
  assert.equal(await source.applyRemoteRelease(newer), "updated");
  assert.deepEqual(events, ["first:remote-updated", "late:remote-updated"]);
  assert.deepEqual(writes.at(-1), {
    path: "synthetic/active",
    text: JSON.stringify(encode(newer), null, 2),
  });
  assert.equal(files.get("synthetic/active")!.endsWith("\n"), false);
  const observerError = new Error("synthetic observer");
  const unsubscribe = source.onDidChange(() => {
    throw observerError;
  });
  const fourth = release(4, "fourth");
  await assert.rejects(source.applyRemoteRelease(fourth), (error) => error === observerError);
  assert.equal(files.get("synthetic/active"), JSON.stringify(encode(fourth), null, 2));
  unsubscribe();

  const trusted = release(5, "trusted"),
    conflicting = release(5, "untrusted");
  put("synthetic/bundle", trusted);
  put("synthetic/active", conflicting);
  assert.equal((await source.read()).providers, trusted.config.providers);
  assert.equal(files.get("synthetic/active"), JSON.stringify(encode(trusted), null, 2));
  files.set("synthetic/active", "invalid synthetic JSON");
  assert.equal((await source.read()).providers, trusted.config.providers);
  const cacheFailure = new Error("synthetic cache unavailable");
  mkdirError = cacheFailure;
  const before = reads.length;
  assert.equal((await source.read()).providers, trusted.config.providers);
  assert.deepEqual(reads.slice(before), ["synthetic/bundle"]);
  await assert.rejects(source.applyRemoteRelease(newer), (error) => error === cacheFailure);
  mkdirError = undefined;
  lockError = cacheFailure;
  assert.equal((await source.read()).providers, trusted.config.providers);
  lockError = undefined;
  files.delete("synthetic/active");
  writeError = cacheFailure;
  assert.equal((await source.read()).providers, trusted.config.providers);
  writeError = undefined;
  const bundleError = new Error("synthetic bundle read"),
    activeError = new Error("synthetic active read");
  readErrors.set("synthetic/bundle", bundleError);
  readErrors.set("synthetic/active", activeError);
  await assert.rejects(source.applyRemoteRelease(newer), (error) => {
    assert.ok(error instanceof AggregateError);
    assert.equal(error.message, "Bundled 与 Active Knorvia Studio Built-in Release 均不可用");
    assert.deepEqual(error.errors, [bundleError, activeError]);
    return true;
  });
  await assert.rejects(source.read(), (error) => {
    assert.ok(error instanceof AggregateError);
    assert.deepEqual(error.errors, [bundleError]);
    return true;
  });
  readErrors.clear();
  put("synthetic/bundle", bundle);
  put("synthetic/active", active);
  source.dispose();
  await assert.rejects(source.read(), {
    message: "NodeKnorviaBuiltinProviderConfigSource 已 dispose",
  });
  await assert.rejects(source.applyRemoteRelease(newer), {
    message: "NodeKnorviaBuiltinProviderConfigSource 已 dispose",
  });
  assert.throws(() => source.onDidChange(() => {}), {
    message: "NodeKnorviaBuiltinProviderConfigSource 已 dispose",
  });
  assert.equal(source.activeFilePath, "synthetic/active");

  const watched = new Source({
    bundledFilePath: "synthetic/bundle",
    activeFilePath: "synthetic/watched",
  });
  const watchedEvents: string[] = [];
  watched.onDidChange((reason) => watchedEvents.push(reason));
  await watched.read();
  const watcher = watchers.at(-1)!;
  const beforeOther = reads.length;
  watcher.callback("rename", "other");
  await flush();
  assert.equal(reads.length, beforeOther);
  put("synthetic/watched", newer);
  watcher.callback("rename", null);
  watcher.callback("change", Buffer.from("watched"));
  await flush();
  assert.deepEqual(watchedEvents, ["file-changed"]);
  watcher.error!();
  assert.deepEqual(watchedEvents, ["file-changed", "watch-error"]);
  watched.dispose();
  watched.dispose();
  assert.equal(watcher.closes, 1);
  watcher.callback("change", null);
  watcher.error!();
  await flush();
  assert.deepEqual(watchedEvents, ["file-changed", "watch-error"]);

  const lateSource = new Source({
    bundledFilePath: "synthetic/bundle",
    activeFilePath: "synthetic/late",
    watch: false,
  });
  put("synthetic/late", active);
  await lateSource.read();
  const lateEvents: string[] = [];
  lateSource.onDidChange((reason) => lateEvents.push(reason));
  writeGate = deferred<void>();
  const pending = lateSource.applyRemoteRelease(newer);
  await flush();
  assert.equal(writes.at(-1)!.path, "synthetic/late");
  lateSource.dispose();
  writeGate.resolve();
  assert.equal(await pending, "updated");
  assert.equal(files.get("synthetic/late"), JSON.stringify(encode(newer), null, 2));
  assert.deepEqual(lateEvents, []);
  writeGate = undefined;

  // 单候选选择不读取 revision 与自身比较；保留解码端口的 getter 可观察顺序。
  let revisionReads = 0;
  const getterRelease: KnorviaBuiltinRelease = {
    ...bundle,
    get revision() {
      revisionReads++;
      return 1;
    },
  };
  tags.set(getterRelease, "getter");
  releases.set("1:getter", getterRelease);
  put("synthetic/getter", getterRelease);
  revisionReads = 0;
  const getterSource = new Source({ bundledFilePath: "synthetic/getter", watch: false });
  await getterSource.read();
  assert.equal(revisionReads, 3);
  getterSource.dispose();

  const closeSource = new Source({ bundledFilePath: "synthetic/bundle" });
  const beforeSame = reads.length,
    beforeWrites = writes.length;
  await closeSource.read();
  assert.deepEqual(reads.slice(beforeSame), ["synthetic/bundle"]);
  assert.equal(writes.length, beforeWrites);
  const closeWatcher = watchers.at(-1)!;
  closeWatcher.closeError = new Error("synthetic close");
  assert.throws(
    () => closeSource.dispose(),
    (error) => error === closeWatcher.closeError,
  );
  closeSource.dispose();
  assert.equal(closeWatcher.closes, 1);
  await assert.rejects(closeSource.read(), {
    message: "NodeKnorviaBuiltinProviderConfigSource 已 dispose",
  });
});

import assert from "node:assert/strict";
import { test } from "node:test";
import type { NodeKnorviaBuiltinProviderConfigSource } from "../src/builtin-provider-config-source.js";
import type { KnorviaBuiltinRelease } from "../src/builtin-release.js";
import type {
  KnorviaBuiltinRefreshEvent,
  KnorviaBuiltinRemoteSynchronizerOptions,
} from "../src/builtin-remote-synchronizer.js";

function deferred<T>() {
  let resolve!: (value: T) => void;
  let reject!: (error: unknown) => void;
  const promise = new Promise<T>((yes, no) => {
    resolve = yes;
    reject = no;
  });
  return { promise, resolve, reject };
}
async function flush() {
  for (let turn = 0; turn < 30; turn++) await Promise.resolve();
}

test("synthetic fetch, control cache and clock preserve leases, failure identity, endpoint generations and cancellation phases", async (t) => {
  const files = new Map<string, string>();
  const writes: { path: string; text: string }[] = [];
  let readError: unknown;
  let atomicError: unknown;
  let atomicFailures = 0;
  let uuid = 0;
  let lockDepth = 0;
  const tails = new Map<string, Promise<void>>();
  t.mock.module("node:crypto", { namedExports: { randomUUID: () => `synthetic-lease-${++uuid}` } });
  t.mock.module("node:fs/promises", {
    namedExports: {
      async readFile(path: string, encoding: string) {
        assert.equal(encoding, "utf8");
        if (readError) throw readError;
        if (!files.has(path))
          throw Object.assign(new Error("synthetic missing control"), { code: "ENOENT" });
        return files.get(path)!;
      },
    },
  });
  t.mock.module("@knorvia/shared/node", {
    namedExports: {
      async atomicWritePrivateTextFile(path: string, text: string) {
        writes.push({ path, text });
        if (atomicFailures-- > 0) throw atomicError;
        files.set(path, text);
      },
      withFileLock<T>(path: string, action: () => Promise<T>) {
        const pending = (tails.get(path) ?? Promise.resolve()).then(async () => {
          lockDepth++;
          try {
            return await action();
          } finally {
            lockDepth--;
          }
        });
        tails.set(
          path,
          pending.then(
            () => {},
            () => {},
          ),
        );
        return pending;
      },
    },
  });
  const { KnorviaBuiltinRemoteSynchronizer: Synchronizer } =
    await import("../src/builtin-remote-synchronizer.js");
  const value = { schemaVersion: 1, revision: 7 } as KnorviaBuiltinRelease;
  let endpoint = " synthetic-endpoint ";
  let now = 100;
  let gate = deferred<KnorviaBuiltinRelease | null>();
  let signal!: AbortSignal;
  let fetchCount = 0;
  let applyCount = 0;
  let applyGate: ReturnType<typeof deferred<"updated" | "unchanged" | "stale">> | undefined;
  let result: "updated" | "unchanged" | "stale" = "updated";
  const events: KnorviaBuiltinRefreshEvent[] = [];
  let throwReport = false;
  const fakeSource = {
    async applyRemoteRelease(release: KnorviaBuiltinRelease) {
      assert.equal(this, fakeSource);
      assert.equal(release, value);
      applyCount++;
      return applyGate ? await applyGate.promise : result;
    },
  };
  const options: KnorviaBuiltinRemoteSynchronizerOptions = {
    source: fakeSource as unknown as NodeKnorviaBuiltinProviderConfigSource,
    controlFilePath: "synthetic/control",
    resolveEndpointKey() {
      assert.equal(this, options);
      return endpoint;
    },
    async fetchRelease(key, abortSignal) {
      assert.equal(this, options);
      assert.equal(key, endpoint.trim());
      assert.equal(lockDepth, 0);
      fetchCount++;
      signal = abortSignal;
      return await gate.promise;
    },
    onRefreshResult(event) {
      assert.equal(this, options);
      events.push(event);
      assert.equal(Object.isFrozen(event), false);
      if (throwReport) throw new Error("synthetic reporting");
    },
    now: function () {
      assert.equal(this, synchronizer);
      return now;
    },
    leaseDurationMs: 20,
    successIntervalMs: 50,
    failureBaseDelayMs: 10,
    failureMaxDelayMs: 15,
  };
  const synchronizer = new Synchronizer(options);
  function control() {
    return JSON.parse(files.get(options.controlFilePath)!) as Record<string, unknown>;
  }
  function put(input: Record<string, unknown>) {
    files.set(options.controlFilePath, JSON.stringify(input));
  }
  const pending = synchronizer.refresh();
  assert.equal(synchronizer.refresh({ force: true }), pending);
  await flush();
  assert.equal(fetchCount, 1);
  assert.equal(signal.aborted, false);
  assert.deepEqual(control(), {
    schemaVersion: 1,
    endpointKey: "synthetic-endpoint",
    leaseId: "synthetic-lease-1",
    leaseUntil: 120,
    nextEligibleAt: 0,
    failureCount: 0,
  });
  assert.deepEqual(Object.keys(control()), [
    "schemaVersion",
    "endpointKey",
    "leaseId",
    "leaseUntil",
    "nextEligibleAt",
    "failureCount",
  ]);
  gate.resolve(value);
  assert.equal(await pending, "updated");
  assert.equal(applyCount, 1);
  assert.deepEqual(events, [{ result: "updated", revision: 7 }]);
  assert.deepEqual(control(), {
    schemaVersion: 1,
    endpointKey: "synthetic-endpoint",
    leaseUntil: 0,
    nextEligibleAt: 150,
    failureCount: 0,
  });
  assert.equal(files.get(options.controlFilePath), JSON.stringify(control(), null, 2));
  assert.equal(files.get(options.controlFilePath)!.endsWith("\n"), false);
  assert.equal(await synchronizer.refresh(), "skipped");
  assert.deepEqual(events.at(-1), { result: "skipped", reason: "not-due" });
  assert.equal(fetchCount, 1);
  put({ ...control(), leaseId: "synthetic-other", leaseUntil: 130, extra: "preserve" });
  const live = files.get(options.controlFilePath);
  assert.equal(await synchronizer.refresh({ force: true }), "skipped");
  assert.deepEqual(events.at(-1), { result: "skipped", reason: "lease-held" });
  assert.equal(files.get(options.controlFilePath), live);
  now = 200;
  gate = deferred();
  result = "stale";
  throwReport = true;
  const forced = synchronizer.refresh({ force: true });
  await flush();
  gate.resolve(value);
  assert.equal(await forced, "stale");
  assert.equal(control().failureCount, 0);
  assert.equal(control().nextEligibleAt, 250);
  throwReport = false;

  now = 300;
  const fetchError = new Error("synthetic fetch failure");
  gate = deferred();
  const failed = synchronizer.refresh();
  await flush();
  gate.reject(fetchError);
  await assert.rejects(failed, (error) => error === fetchError);
  assert.equal(control().failureCount, 1);
  assert.equal(control().nextEligibleAt, 310);
  now = 310;
  gate = deferred();
  const failedAgain = synchronizer.refresh();
  await flush();
  gate.reject(fetchError);
  await assert.rejects(failedAgain, (error) => error === fetchError);
  assert.equal(control().failureCount, 2);
  assert.equal(control().nextEligibleAt, 325);
  now = 325;
  gate = deferred();
  const missing = synchronizer.refresh();
  await flush();
  gate.resolve(null);
  assert.equal(await missing, "missing");
  assert.deepEqual(events.at(-1), { result: "missing" });
  assert.equal(control().failureCount, 0);

  endpoint = "synthetic-new";
  put({ ...control(), failureCount: 9, leaseId: "old", leaseUntil: 9999, nextEligibleAt: 9999 });
  gate = deferred();
  const changed = synchronizer.refresh();
  await flush();
  assert.equal(control().failureCount, 0);
  assert.equal(control().nextEligibleAt, 0);
  const beforeApply = applyCount;
  endpoint = "synthetic-newer";
  gate.resolve(value);
  assert.equal(await changed, "skipped");
  assert.equal(applyCount, beforeApply);
  assert.deepEqual(events.at(-1), { result: "skipped", reason: "endpoint-changed" });
  assert.equal(control().endpointKey, "synthetic-new");
  assert.equal(control().nextEligibleAt, now + 50);

  files.set(options.controlFilePath, "invalid synthetic JSON");
  gate = deferred();
  const corrupt = synchronizer.refresh();
  await flush();
  assert.equal(control().endpointKey, "synthetic-newer");
  const replacement = {
    schemaVersion: 1,
    endpointKey: "synthetic-newer",
    leaseId: "replacement",
    leaseUntil: 777,
    nextEligibleAt: 888,
    failureCount: 4,
    extra: "keep",
  };
  put(replacement);
  const replacedText = files.get(options.controlFilePath);
  gate.resolve(null);
  assert.equal(await corrupt, "missing");
  assert.equal(files.get(options.controlFilePath), replacedText);
  put({ ...replacement, failureCount: -1 });
  gate = deferred();
  const invalid = synchronizer.refresh();
  await flush();
  gate.resolve(null);
  assert.equal(await invalid, "missing");
  assert.equal(control().failureCount, 0);
  // JSON 数字溢出仍是 number；保持原控制文件校验语义，不扩展为有限数修复。
  files.set(
    options.controlFilePath,
    '{"schemaVersion":1,"endpointKey":"synthetic-newer","leaseUntil":1e999,"nextEligibleAt":0,"failureCount":0}',
  );
  assert.equal(await synchronizer.refresh({ force: true }), "skipped");
  assert.deepEqual(events.at(-1), { result: "skipped", reason: "lease-held" });
  const ioError = new Error("synthetic control IO");
  readError = ioError;
  const beforeWrites = writes.length,
    beforeReports = events.length;
  await assert.rejects(synchronizer.refresh({ force: true }), (error) => error === ioError);
  assert.equal(writes.length, beforeWrites);
  assert.equal(events.length, beforeReports);
  readError = undefined;
  endpoint = " ";
  await assert.rejects(synchronizer.refresh(), {
    message: "Knorvia Studio Built-in 远端 Endpoint 不能为空",
  });
  endpoint = "synthetic-newer";
  const forceError = new Error("synthetic force getter");
  assert.throws(
    () =>
      synchronizer.refresh({
        get force(): boolean {
          throw forceError;
        },
      }),
    (error) => error === forceError,
  );

  put({
    schemaVersion: 1,
    endpointKey: "synthetic-newer",
    leaseUntil: 0,
    nextEligibleAt: 0,
    failureCount: 3,
  });
  gate = deferred();
  const cancelled = synchronizer.refresh();
  await flush();
  const aborted = signal;
  synchronizer.dispose();
  assert.equal(aborted.aborted, true);
  gate.resolve(value);
  assert.equal(await cancelled, "disposed");
  assert.equal(control().failureCount, 3);
  assert.equal(control().nextEligibleAt, now);
  assert.equal(control().leaseUntil, 0);
  const disposedOne = synchronizer.refresh(),
    disposedTwo = synchronizer.refresh();
  assert.notEqual(disposedOne, disposedTwo);
  assert.equal(await disposedOne, "disposed");
  await disposedTwo;

  // 新实例仍保留原 options 及其接收者；时钟在构造时捕获。
  let late!: InstanceType<typeof Synchronizer>;
  const lateOptions: KnorviaBuiltinRemoteSynchronizerOptions = {
    ...options,
    controlFilePath: "synthetic/late-control",
    resolveEndpointKey() {
      assert.equal(this, lateOptions);
      return "synthetic-late";
    },
    async fetchRelease(_key, abortSignal) {
      assert.equal(this, lateOptions);
      signal = abortSignal;
      return value;
    },
    now: function () {
      assert.equal(this, late);
      return now;
    },
    onRefreshResult(event) {
      events.push(event);
    },
  };
  late = new Synchronizer(lateOptions);
  applyGate = deferred();
  const latePending = late.refresh();
  await flush();
  const reports = events.length;
  late.dispose();
  applyGate.resolve("updated");
  assert.equal(await latePending, "updated");
  assert.equal(events.length, reports);
  assert.deepEqual(JSON.parse(files.get(lateOptions.controlFilePath)!), {
    schemaVersion: 1,
    endpointKey: "synthetic-late",
    leaseUntil: 0,
    nextEligibleAt: now + 50,
    failureCount: 0,
  });
  applyGate = undefined;

  const initialGate = deferred<string>();
  const initial = new Synchronizer({
    ...lateOptions,
    resolveEndpointKey: () => initialGate.promise,
  });
  const initialPending = initial.refresh();
  const initialWrites = writes.length;
  initial.dispose();
  initialGate.resolve("synthetic-start");
  assert.equal(await initialPending, "disposed");
  assert.equal(writes.length, initialWrites);
  // 完成写入失败会被失败清理替换；保留实际错误身份和第二次清理。
  let finishing!: InstanceType<typeof Synchronizer>;
  const finishOptions = {
    ...lateOptions,
    controlFilePath: "synthetic/finish-control",
    now: function () {
      assert.equal(this, finishing);
      return now;
    },
    resolveEndpointKey: () => "synthetic-finish",
    fetchRelease: async () => {
      atomicFailures = 1;
      return null;
    },
  };
  finishing = new Synchronizer(finishOptions);
  atomicError = new Error("synthetic finish failure");
  await assert.rejects(finishing.refresh(), (error) => error === atomicError);
  assert.equal(JSON.parse(files.get(finishOptions.controlFilePath)!).failureCount, 1);
  finishing.dispose();
});
